HERO_STR_STATIC(hero_str_75b5fbc3, "error: cannot read `");
HERO_STR_STATIC(hero_str_52222bea, "` \342\200\224 `measure` reads its vendored tables from the repository root, and the file it measures by default lives there too");
HERO_STR_STATIC(hero_str_413ee1f4, "error: `");
HERO_STR_STATIC(hero_str_1a7feea7, "` parsed to an empty table");
HERO_STR_STATIC(hero_str_4522508, "   (");
HERO_STR_STATIC(hero_str_4cc9efa0, " ranks)");
HERO_STR_STATIC(hero_str_5ccf48d, "maximum");
HERO_STR_STATIC(hero_str_1c36bf7d, "   a lower bound, not the reader's tokeniser");
HERO_STR_STATIC(hero_str_39cee3d4, "spread");
HERO_STR_STATIC(hero_str_25b820a4, "   between the two vendored tables (");
HERO_STR_STATIC(hero_str_e3f6c6b, "%) \342\200\224 the gap between two REAL tokeniser generations was 967");
HERO_STR_STATIC(hero_str_5c34e23c, "STALE: the recorded count is for ");
HERO_STR_STATIC(hero_str_59255b4a, " and this file is ");
HERO_STR_STATIC(hero_str_2e, ".");
HERO_STR_STATIC(hero_str_1b9dd332, "Run `heroes measure ");
HERO_STR_STATIC(hero_str_2a978d, " --refresh` and paste what it prints.");
HERO_STR_STATIC(hero_str_7668873b, "No verdict is given against a stale count: that is the sentence that");
HERO_STR_STATIC(hero_str_2baac79d, "spent 998 tokens nobody had (docs/measurements/023).");
HERO_STR_STATIC(hero_str_f6133a2, "real");
HERO_STR_STATIC(hero_str_871a0, "   ");
HERO_STR_STATIC(hero_str_29e9670d, " \342\200\224 the binding number");
HERO_STR_STATIC(hero_str_52230a47, "No ceiling judges `");
HERO_STR_STATIC(hero_str_41489909, "` and no check keeps it honest");
HERO_STR_STATIC(hero_str_2a18082d, "(panel 123 R5), so this is a count and not a verdict.");
HERO_STR_STATIC(hero_str_62e135a1, "The two documents that are judged are `");
HERO_STR_STATIC(hero_str_69110222, "` and `");
HERO_STR_STATIC(hero_str_314e, "`.");
HERO_STR_STATIC(hero_str_735bc850, "BREACH: ");
HERO_STR_STATIC(hero_str_678712f1, " over the ");
HERO_STR_STATIC(hero_str_6444bec9, "-token ceiling (design.md \302\2471.6).");
HERO_STR_STATIC(hero_str_2a59cd61, "An amendment must be net-negative, or the ceiling moves \342\200\224 with a");
HERO_STR_STATIC(hero_str_3607815c, "measurement, a panel, and a named alternative (panel 012).");
HERO_STR_STATIC(hero_str_647a5e1d, "An addition needs a named removal or a pre-registered falsifiable");
HERO_STR_STATIC(hero_str_22980fc9, "prediction (panel 012). ");
HERO_STR_STATIC(hero_str_1decd800, "Headroom: ");
HERO_STR_STATIC(hero_str_45293617, " against the contract's own ");
HERO_STR_STATIC(hero_str_4011a92c, ", which is a ceiling and not a pin: the repair for crossing it is to move a story into docs/records/contract/case-law.md, never a bigger number.");
HERO_STR_STATIC(hero_str_452e9c7c, " against the ");
HERO_STR_STATIC(hero_str_2c5ebfc7, " ceiling \342\200\224 but the FFI floor mortgages ");
HERO_STR_STATIC(hero_str_54314e0d, " of it (panel 030 R3), so what is measured against the ceiling is ");
HERO_STR_STATIC(hero_str_3c33f96a, " and the check goes red at ");
HERO_STR_STATIC(hero_str_e26a397, "unused");
HERO_STR_STATIC(hero_str_3c921d75, "plain");
HERO_STR_STATIC(hero_str_2652efaa, "examples");
HERO_STR_STATIC(hero_str_78438baf, "error: no operator `");
HERO_STR_STATIC(hero_str_8cce658, "`\n  the ");
HERO_STR_STATIC(hero_str_269ca4be, " are: ");
HERO_STR_STATIC(hero_str_74e2afb1, "error: no `.hero` files under ");
HERO_STR_STATIC(hero_str_4655a35e, "corpus: ");
HERO_STR_STATIC(hero_str_716c0ac5, " programs under ");
HERO_STR_STATIC(hero_str_13ab0ca5, "no_corpus");
HERO_STR_STATIC(hero_str_3580f6de, ".hero");
HERO_STR_STATIC(hero_str_7d99834b, "every program compiles");
HERO_STR_STATIC(hero_str_452bbd46, "this corpus does not compile, so its kill rate would be meaningless\n  ");
HERO_STR_STATIC(hero_str_466f899, " of ");
HERO_STR_STATIC(hero_str_26738cc6, " programs are already refused by `heroes check`:\n");
HERO_STR_STATIC(hero_str_4522500, "    ");
HERO_STR_STATIC(hero_str_7042178b, "  every mutant of a program that is already wrong is killed by the\n  diagnostic that was already there \342\200\224 run `heroes check` on each");
HERO_STR_STATIC(hero_str_46dbcb10, "Heroes: the terminals and the precedence, read from the compiler's own tables.\n\n");
HERO_STR_STATIC(hero_str_528, "\n\n");
HERO_STR_STATIC(hero_str_275e9aaf, "Keywords (");
HERO_STR_STATIC(hero_str_c080db1, "), which a program may not use as a name:");
HERO_STR_STATIC(hero_str_2aeda, "\n  ");
HERO_STR_STATIC(hero_str_5dba8d57, "Binary operators, loosest first. Every one is left-associative, so the\nclimber asks for `power + 1` on the right. The `operator` column is the name\nthe tree carries, and a spelling paired with the wrong one parses as the wrong\noperator with every test green (panel 067).\n");
HERO_STR_STATIC(hero_str_1dcd4e6d, "\n  power  spelling  operator");
HERO_STR_STATIC(hero_str_6278e1a6, " IS IN THE LIST AND NOT IN THE TABLE");
HERO_STR_STATIC(hero_str_4b79326b, "The productions are in `");
HERO_STR_STATIC(hero_str_7a260b80, "`, which is not readable from here.\nThis command reads it relative to the working directory, as `measure` reads its\ntables, so run it from the repository to see them collected.");
HERO_STR_STATIC(hero_str_3b27f5fe, "Productions, collected from `");
HERO_STR_STATIC(hero_str_32474f85, "`, where each is authored beside the\nprose that governs it. `=` defines and `.` ends, `|` alternates, `[ ]` is\noptional, `{ }` repeats zero or more times.");
HERO_STR_STATIC(hero_str_5db5ff2e, "Not here, because the compiler holds no table to print it from: the six\ncontextual words \342\200\224 `as`, `link`, `package`, `tag`, `partial`, `owned` \342\200\224 which\nare ordinary identifiers everywhere except the one position each is read in.\n\nAnd nothing above is checked against the parser. The keywords and the powers\nare read from the compiler's own tables, so they cannot drift from it; the\nproductions are checked for internal consistency only, which is `ebnflint`'s\nclass and Go's. No instrument compares a production to the function that reads\nit.");
