HERO_STR_STATIC(hero_str_528c02f1, "` is not `");
HERO_STR_STATIC(hero_str_1181cf32, "` in `");
HERO_STR_STATIC(hero_str_72063df6, "` \342\200\224 clang read the header and the types disagree");
HERO_STR_STATIC(hero_str_339821de, "an `extern constant` takes its value from the header (\302\2474.19), so its type is the header's too: correct the declared type, or name the header that spells `");
HERO_STR_STATIC(hero_str_1070b187, "` as `");
HERO_STR_STATIC(hero_str_32f20594, "` does not return `");
HERO_STR_STATIC(hero_str_48cc5ea1, "` \342\200\224 that is what `");
HERO_STR_STATIC(hero_str_7fb4af4b, "` says, and clang read it");
HERO_STR_STATIC(hero_str_3bdd0bd2, "an `extern` is checked against the real header (\302\2474.19): correct the result type, or name the header that declares this `");
HERO_STR_STATIC(hero_str_3d643630, "not a constancy assertion");
HERO_STR_STATIC(hero_str_31d5203c, "the marker's tail is empty");
HERO_STR_STATIC(hero_str_11905d6e, "ffi_not_constant");
HERO_STR_STATIC(hero_str_6236fb02, "` has `");
HERO_STR_STATIC(hero_str_21a446e3, "`, but not as a constant \342\200\224 clang cannot read its value while compiling");
HERO_STR_STATIC(hero_str_5a8370f8, "a `constant` names one value forever (\302\2474.4), and `");
HERO_STR_STATIC(hero_str_6244093a, "` is an object or a macro that expands to one \342\200\224 reading it twice could give two answers, which is the mutable global \302\2474.2 forbids. A C object is reached through an `extern function` that returns it");
HERO_STR_STATIC(hero_str_7f5b0549, "call to undeclared function '");
HERO_STR_STATIC(hero_str_74692024, "call to undeclared library function '");
HERO_STR_STATIC(hero_str_76b3a9fb, "use of undeclared identifier '");
HERO_STR_STATIC(hero_str_61f6e6aa, "not an undeclared-name line");
HERO_STR_STATIC(hero_str_313ef0e4, "must use 'struct' tag to refer to type '");
HERO_STR_STATIC(hero_str_3da6e00e, "the tag class owns this name");
HERO_STR_STATIC(hero_str_56a08d2, "ffi_unknown_name");
HERO_STR_STATIC(hero_str_13a84ace, "` declares no `");
HERO_STR_STATIC(hero_str_4e380f0a, "` \342\200\224 clang read the header and could not find it");
HERO_STR_STATIC(hero_str_4984a51, "an `extern` names what the header already has (\302\2474.19): check the spelling, or name the header that does declare `");
HERO_STR_STATIC(hero_str_2d81771, "the header declares `");
HERO_STR_STATIC(hero_str_70ce66e, "did you mean");
HERO_STR_STATIC(hero_str_1fc2f816, "did you mean '");
HERO_STR_STATIC(hero_str_74547321, "clang offered no correction");
HERO_STR_STATIC(hero_str_289260c, "heroes-ffi-pointee ");
HERO_STR_STATIC(hero_str_4d84c306, "heroes-ffi-pointee-void ");
HERO_STR_STATIC(hero_str_26b86bda, "no such parameter on an extern of that name");
HERO_STR_STATIC(hero_str_27bef920, "not a pointee assertion");
HERO_STR_STATIC(hero_str_61b4c870, "a width the header does not have");
HERO_STR_STATIC(hero_str_62e3d0a4, "` is declared ");
HERO_STR_STATIC(hero_str_286dd996, ", and the header's `");
HERO_STR_STATIC(hero_str_3d501578, " *` points at a different width or sign \342\200\224 clang read the header, and C writes back exactly the bytes the header expects");
HERO_STR_STATIC(hero_str_f65f7aa, "\302\2474.19: a C out-parameter is an `@` parameter, and what it points at is held to the header's own width and sign \342\200\224 `u64` where it says `size_t *`, `i32` where it says `int *`");
HERO_STR_STATIC(hero_str_419319f1, "` has no name in this language yet \342\200\224 declare the parameter at its width and sign, and say which in a comment beside the declaration");
